
<div class="heading"><div><h1>Reportes y analítica</h1><small>Decisiones basadas en las ventas reales de tu tienda.</small></div><a class="btn-link" href="exportar.php?start=<?=e($start)?>&amp;end=<?=e($end)?>">Exportar CSV</a></div>
<div class="panel"><form method="get" class="form-grid"><input type="hidden" name="page" value="reportes"><label>Desde<input type="date" name="start" value="<?=e($start)?>"></label><label>Hasta<input type="date" name="end" value="<?=e($end)?>"></label><div class="full"><button class="primary">Filtrar</button></div></form></div>
<div class="stats"><div class="stat"><small>VENTAS TOTALES</small><strong><?=money($tot['revenue'])?></strong></div><div class="stat"><small>UNIDADES VENDIDAS</small><strong><?=e($margin['units'])?></strong></div><div class="stat"><small>MARGEN BRUTO</small><strong class="green"><?=money($margin['margin'])?></strong></div><div class="stat"><small>TICKET PROMEDIO</small><strong><?=money($tot['sales']?($tot['revenue']/$tot['sales']):0)?></strong></div></div>
<div class="two-col"><div class="panel"><h3>Ventas por día</h3><div class="bars"><?php $max=$days ? max(1,...array_map(fn($r)=>(float)$r['total'],$days)) : 1;foreach($days as $r):?><div><div class="bar-label"><span><?=e($r['day'])?></span><strong><?=money($r['total'])?></strong></div><div class="bar-track"><div class="bar-fill" style="width:<?=e(round(100*$r['total']/$max))?>%"></div></div></div><?php endforeach;?><?php if(!$days):?><p class="empty">Sin ventas en este período.</p><?php endif;?></div></div><div class="panel"><h3>Métodos de pago</h3><table><thead><tr><th>Método</th><th>Ventas</th><th>Ingresos</th></tr></thead><tbody><?php foreach($methods as $m):?><tr><td><?=e($m['payment_method'])?></td><td><?=e($m['qty'])?></td><td><?=money($m['amount'])?></td></tr><?php endforeach;?></tbody></table><h3 style="margin-top:25px">Categorías más vendidas</h3><table><thead><tr><th>Categoría</th><th>Unidades</th><th>Ingresos</th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><?=e($c['category'])?></td><td><?=e($c['units'])?></td><td><?=money($c['revenue'])?></td></tr><?php endforeach;?></tbody></table></div></div>